        if node.kind() == "identifier" {
            if let Some(klass) = classify_identifier(node) {
                map.insert(node.start_byte(), klass);
            }
        }
        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            stack.push(child);
        }
    }
    map
