    println!("{}{} [{}..{}]{}", "  ".repeat(depth), node.kind(), node.start_byte(), node.end_byte(), text);
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) { dump(child, source, depth + 1); }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let src = std::fs::read_to_string(&args[1]).unwrap();
    let mut parser = Parser::new();
    parser.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
    let tree = parser.parse(&src, None).unwrap();
    dump(tree.root_node(), &src, 0);
}
